FICHES.append(fiche(
 id='immigres-crise-logement', affirmation="Les immigrés sont responsables de la crise du logement : s'il y en avait moins, tout le monde pourrait se loger.", volet='immigration', sous_theme='Logement',
 mots_cles=['immigres crise du logement', 'les immigres prennent nos logements', 'crise du logement immigration', 'pas de logement a cause des immigres', 'penurie de logements immigres', 'mises en chantier chute', 'logements vacants residences secondaires', 'mal logement fondation', 'surpeuplement immigres', 'on ne trouve plus a se loger'],
 verdict='trompeur', fiabilite='interpretation',
 resume="Les causes de la crise du logement identifiées par le Sénat, l'Insee et le ministère sont ailleurs : effondrement de la construction après la hausse des taux d'intérêt, prix multipliés par plus de deux en vingt-cinq ans, ménages plus petits (vieillissement, séparations), résidences secondaires et logements vacants (près de 7 millions au total). Les immigrés sont plus souvent locataires HLM (35 % contre 11 %), mais surtout parce qu'ils sont plus pauvres et plus jeunes, et ils sont parmi les premiers à subir la crise : 26 % vivent dans un logement surpeuplé.",
 contexte="L'idée qu'on manquerait de logements « à cause des immigrés » revient dans les débats sur la préférence nationale. La question de l'attribution des HLM est traitée dans une autre fiche ; celle-ci porte sur les causes de la crise du logement dans son ensemble.",
 explication="On rassemble les causes de la crise établies par un rapport du Sénat et par la statistique publique (construction, parc de logements, taille des ménages), puis on regarde la place et les conditions de logement des immigrés, à partir de l'Insee.",
 sources=[C_LOG_SENAT, C_LOG_SDES, C_LOG_PARC, C_LOG_TEO, C_LOG_FLD],
 faits=[
  fait("Selon le rapport du Sénat sur la crise du logement, en 2023 les mises en chantier ont chuté de 22 % (287 000) et les permis de construire de 24 %, la construction neuve est « au plus bas depuis 1995 » et la production de crédit immobilier a baissé de plus de moitié en dix-huit mois.", 'c_log_senat', '2022-2023', 'France', "La crise récente est d'abord un effondrement de l'offre, lié à la remontée des taux d'intérêt.", 'etabli', '-22 %'),
  fait("Selon le service statistique du ministère, 274 611 logements ont été mis en chantier en 2025, soit 21,3 % de moins que la moyenne des cinq années précédentes.", 'c_log_sdes', '2020-2025', 'France', "La construction ne s'est pas relevée : on construit nettement moins qu'avant la crise.", 'etabli', '-21,3 %'),
  fait("Selon le même rapport du Sénat, les taux d'intérêt très bas, « 1 % voire moins », et l'argent bon marché ont fait exploser les prix, « multipliés par plus de deux » en vingt-cinq ans ; le rapport cite aussi le « desserrement des ménages », le vieillissement, l'attrait des résidences secondaires et la métropolisation.", 'c_log_senat', '1999-2024', 'France', "Les causes identifiées par les parlementaires sont financières, démographiques et territoriales ; l'immigration n'y figure pas dans la partie lue.", 'interpretation', 'x2'),
  fait("Selon l'Insee, au 1er janvier 2024, la France compte 38,2 millions de logements, dont 3,7 millions de résidences secondaires ou occasionnelles et 3,1 millions de logements vacants ; la part des logements vacants est passée de 6,3 % en 2005 à 8,0 %.", 'c_log_parc', '2005-2024', 'France hors Mayotte', "Près de 7 millions de logements ne servent pas de résidence principale : la question est aussi celle de leur usage.", 'etabli', '3,1 millions'),
  fait("Selon l'Insee, le parc de logements croît plus vite que la population parce que « le nombre de personnes par logement diminue » : mise en couple plus tardive, séparations plus fréquentes, vieillissement.", 'c_log_parc', '1982-2024', 'France', "À population égale, il faut toujours plus de logements : c'est un moteur majeur des besoins, indépendant de l'immigration.", 'etabli'),
  fait("Fait défavorable : selon l'Insee, 35 % des immigrés de 18 à 59 ans vivent dans un ménage locataire du secteur social, contre 11 % des personnes sans ascendance migratoire ; cette surreprésentation « est largement liée aux moindres revenus et à l'âge plus jeune ».", 'c_log_teo', '2019-2020', 'France métropolitaine', "Les immigrés occupent bien une part importante du parc social, mais au titre de critères sociaux, pas de leur origine.", 'etabli', '35 % contre 11 %'),
  fait("Selon l'Insee, 26 % des immigrés de 18 à 59 ans vivent dans un logement surpeuplé, contre 8 % des personnes sans ascendance migratoire ; 23 % vivent en quartier prioritaire, contre 7 % de l'ensemble.", 'c_log_teo', '2019-2020', 'France métropolitaine', "Les immigrés sont parmi les premières victimes de la crise du logement, pas ses responsables.", 'etabli', '26 %'),
  fait("Selon le rapport 2026 de la Fondation pour le logement des défavorisés, rapporté par Maire-info, 4,2 millions de personnes sont sans logement ou mal logées, 350 000 sans domicile (contre 143 000 en 2012), et près de 2,9 millions attendent un logement social ; la fondation met en cause une réponse politique « loin d'être à la hauteur ».", 'c_log_fld', '2012-2025', 'France', "Le mal-logement touche toutes les origines ; la fondation pointe le recul de la production et des politiques publiques.", 'estimation', '4,2 millions'),
 ],
 court="Non. Les causes de la crise identifiées par le Sénat et la statistique publique sont l'effondrement de la construction après la hausse des taux, des prix multipliés par plus de deux en vingt-cinq ans, des ménages plus petits et près de 7 millions de logements vacants ou secondaires. Les immigrés sont plus souvent en HLM parce qu'ils sont plus pauvres, et 26 % vivent dans un logement surpeuplé : ils subissent la crise.",
 moyen="La crise du logement a des causes bien documentées. Le Sénat montre qu'en 2023 les mises en chantier ont chuté de 22 % et la construction neuve est tombée au plus bas depuis 1995, après la remontée des taux d'intérêt ; en 2025, on construisait encore 21 % de moins que la moyenne des cinq années précédentes, selon le ministère. Les prix ont plus que doublé en vingt-cinq ans. Et à population égale il faut toujours plus de logements, car les ménages sont plus petits (vieillissement, séparations), explique l'Insee. S'y ajoutent 3,7 millions de résidences secondaires et 3,1 millions de logements vacants.\n\nLes immigrés, eux, sont plus souvent locataires HLM (35 % contre 11 %), mais l'Insee l'explique par leurs revenus plus faibles et leur âge. Ils sont surtout parmi les plus mal logés : 26 % vivent dans un logement surpeuplé, trois fois plus que les autres.",
 detaille="Désigner les immigrés comme responsables de la crise du logement, c'est passer à côté de toutes les causes établies.\n\nPremière cause : on ne construit plus assez. Selon le rapport du Sénat d'avril 2024, les mises en chantier ont chuté de 22 % en 2023 et les permis de 24 % ; la construction neuve était « au plus bas depuis 1995 », et la production de crédit immobilier avait baissé de plus de moitié en dix-huit mois avec la remontée des taux. En 2025, malgré une reprise des permis, 274 611 logements seulement ont été mis en chantier, 21,3 % de moins que la moyenne des cinq années précédentes, selon le service statistique du ministère.\n\nDeuxième cause : les prix. Les sénatrices rappellent que les taux très bas et l'argent bon marché les ont « multipliés par plus de deux » en vingt-cinq ans. Le logement est devenu un placement autant qu'un besoin.\n\nTroisième cause : la transformation des ménages. Selon l'Insee, le parc de logements croît plus vite que la population parce que le nombre de personnes par logement diminue : on se met en couple plus tard, on se sépare plus souvent, on vit plus longtemps, souvent seul. Il faut donc toujours plus de logements pour le même nombre d'habitants.\n\nQuatrième cause : l'usage du parc. Sur 38,2 millions de logements, 3,7 millions sont des résidences secondaires ou occasionnelles et 3,1 millions sont vacants, une part en hausse depuis 2005.\n\nEt les immigrés ? Selon l'Insee, 35 % des immigrés de 18 à 59 ans vivent dans un ménage locataire HLM, contre 11 % des personnes sans ascendance migratoire, une différence « largement liée aux moindres revenus et à l'âge plus jeune ». Ils sont surtout parmi les plus mal logés : 26 % vivent dans un logement surpeuplé, contre 8 %. La Fondation pour le logement des défavorisés compte 4,2 millions de personnes mal logées et 350 000 sans domicile : la crise frappe les plus pauvres, quelle que soit leur origine. La réponse, c'est construire massivement du logement social, mobiliser les logements vacants et encadrer les loyers, pas trier les mal-logés.",
 empathie="Chercher un logement aujourd'hui peut être épuisant et humiliant, et la colère est compréhensible. Mais cette colère mérite d'être dirigée vers les vraies causes, pour que les choses changent vraiment.",
 legitimes=["Les immigrés sont surreprésentés parmi les locataires HLM, c'est mesuré par l'Insee.", "Toute hausse de la population, quelle qu'en soit l'origine, accroît les besoins en logements.", "L'attente pour un logement social est très longue et nourrit un sentiment d'injustice."],
 contre=[
  ("Les immigrés prennent les HLM.", "Ils y sont surreprésentés (35 % contre 11 %) parce qu'ils sont plus pauvres et plus jeunes, selon l'Insee. Et le vrai problème est qu'on ne construit pas assez : le Sénat compte 2,6 millions de demandeurs pour 82 000 nouveaux agréments en 2023."),
  ("Sans immigration, il y aurait assez de logements.", "Les causes identifiées par le Sénat et l'Insee sont l'effondrement de la construction, les prix, les ménages plus petits, les résidences secondaires et la vacance. Même sans immigration, ces facteurs resteraient."),
  ("On loge les migrants avant les Français.", "Les immigrés sont parmi les plus mal logés : 26 % vivent dans un logement surpeuplé, contre 8 % des personnes sans ascendance migratoire, selon l'Insee."),
 ],
 questions=["Si on construit beaucoup moins de logements qu'avant, qui en est responsable : les immigrés ou les choix politiques ?", "Que pourrait-on faire des 3,1 millions de logements vacants ?"],
 limites=["Le rapport du Sénat a été lu à travers un outil de lecture qui résume, et seule sa première partie l'a été ; ses chiffres portent sur 2023.", "Le rapport de la Fondation pour le logement des défavorisés n'a pas été ouvert directement : ses chiffres viennent d'un article de Maire-info.", "Les données de l'Insee sur les immigrés datent de 2019-2020 et portent sur les 18-59 ans en France métropolitaine.", "Aucune des sources lues ne chiffre la part de l'immigration dans la hausse des besoins en logements ; la fiche ne prétend pas qu'elle est nulle, mais qu'elle n'est pas désignée comme une cause de la crise par ces sources.", "Les pages ont été lues à travers un outil de lecture qui résume ; les citations sont à revérifier mot pour mot."],
 publics={'convaincus': "Je comprends que tu galères ou que tu voies tes enfants galérer pour se loger. Mais le Sénat, toutes tendances confondues, explique la crise par l'effondrement de la construction, les prix qui ont doublé et les ménages plus petits. Et les immigrés vivent trois fois plus souvent que les autres dans des logements surpeuplés : ils sont dans la même galère que toi, souvent pire.",
  'indecis': "Ton inquiétude est légitime : se loger est devenu très difficile. Les causes sont connues : on construit 21 % de moins qu'il y a quelques années, les prix ont plus que doublé en vingt-cinq ans, et il y a plus de 3 millions de logements vacants. Les immigrés sont plus souvent en HLM parce qu'ils sont plus pauvres, mais ils sont aussi parmi les plus mal logés."},
 a_actualiser='2027-02-15', raison="Nouveau rapport annuel sur l'état du mal-logement et bilan annuel de la construction de logements.",
))

# 3 ── « La France est le pays qui dépense le plus en protection sociale au monde » ──────────────
C_PS_ER = ('c_ps_er', src("Les dépenses sociales ont augmenté partout en Europe entre 2007 et 2023, à quelques exceptions près (Études et Résultats n° 1357)", 'Drees (Clément Dherbécourt, Mathilde Didier)', 'décembre 2025',
  'https://drees.solidarites-sante.gouv.fr/sites/default/files/2025-12/ER%201357%20D%C3%A9penses%20sociales.pdf',
  "« La France est en 2023 le premier pays européen pour la part de la dépense sociale dans le PIB » (31,7 points de PIB potentiel), devant la Finlande (31,1), l'Autriche (30,0) et l'Allemagne (28,8). En moyenne dans l'UE-27, la dépense sociale est passée « de 24,9 % à 27,2 % du PIB » entre 2007 et 2023. En 2024, « Les dépenses sociales s'élèvent à 32,5 % du PIB courant en Finlande, à 31,9 % en France et à 31,8 % en Autriche » : la Finlande « prendrait la première place en 2024 ». « 80 % d'entre elles concernent les risques maladie et vieillesse ».",
  "Étude de la direction statistique des ministères sociaux, sur données harmonisées européennes (lue à travers un outil de lecture qui résume).", 'primaire'))
C_PS_FICHE = ('c_ps_fiche', src("Les dépenses de protection sociale en 2024 (fiche 03, La protection sociale en France et en Europe en 2024, édition 2025)", 'Drees', 'décembre 2025',
  'https://www.drees.solidarites-sante.gouv.fr/sites/default/files/2026-05/CPS2025%20-%20Fiche%2003%20-%20Les%20d%C3%A9penses%20de%20protection%20sociale%20en%202024.pdf',
  "En 2024, les dépenses de protection sociale « atteignent 982,2 milliards d'euros », soit « 33,6 % du produit intérieur brut (PIB) » (33,1 % en 2023). Les prestations sociales représentent 94 % des dépenses, « pour un total de 932,5 milliards d'euros » : vieillesse-survie 426,7 Md€ (45,8 %), santé 338,9 Md€ (36,3 %), famille 65,8 Md€ (7,1 %), emploi 51,1 Md€ (5,5 %), pauvreté et exclusion sociale 34,0 Md€, logement 16,1 Md€ (1,7 %).",
  "Fiche du panorama annuel des comptes de la protection sociale (lue à travers un outil de lecture qui résume ; la date de la fiche n'est pas indiquée, l'édition 2025 est parue en décembre 2025).", 'primaire'))
C_PS_OCDE = ('c_ps_ocde', src("Sizing up Welfare States: How do OECD countries compare?", 'OCDE, direction de l\'emploi, du travail et des affaires sociales (Willem Adema, Pauline Fron, Maxime Ladaique)', '2 février 2023',
  'https://oecdstatistics.blog/2023/02/02/sizing-up-welfare-states-how-do-oecd-countries-compare/',
  "Dépenses sociales publiques de la France « At over 30% of GDP in 2022 » ; moyenne de l'OCDE passée de 23 % en 2020 à environ 21 % en 2022 (estimation). « France is the biggest social spender according to both gross public and net total social expenditure indicators ». En intégrant les dépenses sociales privées et les avantages fiscaux à but social (dépenses sociales nettes totales), les États-Unis passent de la 23e place pour les dépenses publiques brutes à la 2e place.",
  "Article du blog statistique officiel de l'OCDE, écrit par les responsables de la base SOCX (lu à travers un outil de lecture qui résume) ; données 2022 et années antérieures pour les dépenses nettes.", 'primaire'))
C_PS_MS = ('c_ps_ms', src("Les effets des transferts sociaux et fiscaux sur la réduction de la pauvreté monétaire (fiche 03, Minima sociaux et prestations de solidarité, édition 2025)", 'Drees', 'décembre 2025',
  'https://drees.solidarites-sante.gouv.fr/sites/default/files/2025-12/MS2025%20-%20Fiche%2003%20-%20Les%20effets%20des%20transferts%20sociaux%20et%20fiscaux%20sur%20la%20r%C3%A9duction%20de%20la%20pauvret%C3%A9%20mon%C3%A9taire.pdf',
  "En 2022 (enquête ERFS), le taux de pauvreté monétaire au seuil de 60 % passe de 21,3 % avant transferts à 14,4 % après : « Les prestations sociales non contributives et les impôts directs diminuent le taux de pauvreté monétaire de 6,9 points ». Contributions : prestations familiales -1,7 point, minima sociaux -1,7, prime d'activité -1,4, allocations logement -1,1, impôts directs -0,7. « Les prestations sociales non contributives ont donc un effet beaucoup plus fort que les impôts directs ».",
  "Fiche de l'ouvrage annuel de la Drees (lue à travers un outil de lecture qui résume) ; le revenu « avant transferts » inclut déjà les pensions de retraite et les allocations chômage.", 'primaire'))

FICHES.append(fiche(
 id='france-championne-depenses-sociales', affirmation="La France est le pays qui dépense le plus en protection sociale au monde, c'est un gouffre sans résultat.", volet='social', sous_theme='Coût et efficacité des aides',
 mots_cles=['france championne du monde des depenses sociales', 'pays qui depense le plus en protection sociale', 'depenses sociales part du pib', 'protection sociale gouffre', 'modele social trop cher', 'trop de depenses sociales', 'record mondial depenses sociales', 'ocde depenses sociales france', 'protection sociale 33 % du pib', 'prestations sociales a quoi ca sert'],
 verdict='plutot_exact', fiabilite='etabli',
 resume="Pour l'essentiel, c'est vrai : la France est en tête ou presque. Selon l'OCDE, elle est le premier pays pour les dépenses sociales publiques (plus de 30 % du PIB en 2022) ; selon la Drees, elle était première de l'Union européenne en 2023, et passerait deuxième derrière la Finlande en 2024. Mais cet argent finance d'abord les retraites (46 % des prestations) et la santé (36 %), et quand on ajoute les dépenses privées, les États-Unis remontent au 2e rang. Quant à l'efficacité, les prestations sociales font baisser le taux de pauvreté de 21,3 % à 14,4 %.",
 contexte="L'argument sert à justifier des coupes dans les prestations sociales ou à présenter le modèle social comme un luxe inefficace. Il s'appuie sur des comparaisons internationales réelles, mais oublie ce que ces dépenses financent et ce qu'elles évitent.",
 explication="On vérifie le classement (Drees, OCDE), puis on regarde ce que finance la dépense, ce qu'on obtient en tenant compte des dépenses privées, et l'effet des prestations sur la pauvreté.",
 sources=[C_PS_ER, C_PS_FICHE, C_PS_OCDE, C_PS_MS],
 faits=[
  fait("Fait défavorable : selon la Drees, « La France est en 2023 le premier pays européen pour la part de la dépense sociale dans le PIB », avec 31,7 points de PIB potentiel, contre 27,2 % en moyenne dans l'Union européenne.", 'c_ps_er', '2023', 'Union européenne', "Le constat de départ est exact : la France consacre une part de sa richesse à la protection sociale parmi les plus élevées.", 'etabli', '31,7 %'),
  fait("Selon la Drees, en 2024, la dépense sociale atteint 32,5 % du PIB en Finlande, 31,9 % en France et 31,8 % en Autriche : la Finlande prendrait la première place européenne.", 'c_ps_er', '2024', 'Union européenne', "La France n'est pas seule : plusieurs pays européens dépensent autant, et certains ont pris la tête.", 'estimation', '31,9 %'),
  fait("Selon l'OCDE (données 2022), la France est le pays qui dépense le plus pour le social, à plus de 30 % du PIB en dépenses publiques, contre environ 21 % en moyenne dans l'OCDE.", 'c_ps_ocde', '2022', 'Pays de l\'OCDE', "À l'échelle des pays riches, la France est bien en tête pour la dépense publique sociale.", 'etabli', '+30 %'),
  fait("Selon l'OCDE, en ajoutant les dépenses sociales privées et les avantages fiscaux à but social, les États-Unis passent de la 23e place à la 2e place des pays de l'OCDE.", 'c_ps_ocde', '2022', 'Pays de l\'OCDE', "Les Américains ne dépensent pas beaucoup moins pour se protéger : ils le font surtout par des assurances privées, plus inégalitaires.", 'etabli', '23e → 2e'),
  fait("Selon la Drees, en 2024, les dépenses de protection sociale atteignent 982,2 milliards d'euros, soit 33,6 % du PIB ; sur 932,5 milliards de prestations, 426,7 milliards vont à la vieillesse-survie (45,8 %) et 338,9 milliards à la santé (36,3 %).", 'c_ps_fiche', '2024', 'France', "Plus de 80 % de la dépense sert aux retraites et aux soins : ce ne sont pas des « aides » pour quelques-uns, mais des droits pour tous.", 'etabli', '982,2 Md€'),
  fait("Selon la Drees, en 2024, les prestations du risque pauvreté et exclusion sociale (dont le RSA) représentent 34,0 milliards d'euros, et celles du logement 16,1 milliards.", 'c_ps_fiche', '2024', 'France', "Les minima sociaux, souvent visés, ne pèsent qu'une petite part de l'ensemble.", 'etabli', '34,0 Md€'),
  fait("Selon la Drees, en 2022, les prestations sociales non contributives et les impôts directs font baisser le taux de pauvreté de 21,3 % à 14,4 %, soit 6,9 points ; les prestations familiales, les minima sociaux, la prime d'activité et les allocations logement en expliquent l'essentiel.", 'c_ps_ms', '2022', 'France métropolitaine', "La dépense a un résultat mesurable : sans elle, environ une personne sur cinq serait pauvre.", 'etabli', '-6,9 points'),
 ],
 court="En part de PIB, c'est presque vrai : la France était première de l'Union européenne en 2023 et première de l'OCDE en dépenses sociales publiques, selon la Drees et l'OCDE. Mais 82 % des prestations vont aux retraites et à la santé, les États-Unis remontent au 2e rang quand on compte les assurances privées, et les prestations font baisser la pauvreté de 21,3 % à 14,4 %. Ce n'est pas un gouffre, c'est un choix.",
 moyen="Le classement est globalement juste. Selon la Drees, la France était en 2023 le premier pays européen pour la dépense sociale rapportée au PIB, et passerait au deuxième rang derrière la Finlande en 2024. Selon l'OCDE, elle est aussi en tête des pays riches pour les dépenses sociales publiques, à plus de 30 % du PIB en 2022.\n\nMais il faut voir ce que cela recouvre. Sur 932,5 milliards de prestations en 2024, 426,7 milliards financent les retraites et 338,9 milliards la santé. Ailleurs, ces dépenses passent souvent par le privé : en les comptant, les États-Unis remontent de la 23e à la 2e place, selon l'OCDE. Et le résultat est mesurable : les prestations sociales et les impôts font baisser le taux de pauvreté de 21,3 % à 14,4 %, selon la Drees.",
 detaille="Commençons par reconnaître ce qui est exact. Selon la Drees, la France était en 2023 le premier pays de l'Union européenne pour la part de la dépense sociale dans la richesse nationale, avec près de 32 % contre 27 % en moyenne. En 2024, la Finlande (32,5 %) passerait devant la France (31,9 %), talonnée par l'Autriche (31,8 %). Selon l'OCDE, la France est aussi le pays qui consacre le plus de dépenses publiques au social parmi les pays riches, à plus de 30 % du PIB en 2022, contre environ 21 % en moyenne.\n\nMais à quoi sert cet argent ? En 2024, les dépenses de protection sociale atteignent 982,2 milliards d'euros selon la Drees. Sur 932,5 milliards de prestations, 426,7 milliards vont aux pensions de retraite et de réversion, 338,9 milliards à la santé. Les prestations contre la pauvreté (dont le RSA) représentent 34 milliards, le logement 16 milliards. Autrement dit, l'essentiel finance des droits universels dont tout le monde profite au cours de sa vie.\n\nEnsuite, comparer les seules dépenses publiques est trompeur. Dans d'autres pays, retraites et santé passent par des assurances privées, souvent obligatoires ou encouragées fiscalement. L'OCDE a calculé qu'en tenant compte de ces dépenses privées et des avantages fiscaux, les États-Unis passent de la 23e à la 2e place. La différence n'est pas tant le montant que le mode de financement : collectif et solidaire d'un côté, individuel et inégalitaire de l'autre.\n\nEnfin, la dépense produit des résultats. Selon la Drees, en 2022, les prestations sociales non contributives et les impôts directs font baisser le taux de pauvreté de 21,3 % à 14,4 %. Les prestations familiales, les minima sociaux, la prime d'activité et les allocations logement en sont les principaux leviers. Et ce calcul n'inclut même pas l'effet des retraites, déjà comptées dans le revenu de départ.\n\nLe vrai débat n'est donc pas « trop de dépenses », mais quel modèle on veut : une protection publique qui couvre tout le monde, ou un système où chacun paie selon ses moyens, et où les plus pauvres renoncent.",
 empathie="C'est vrai que les chiffres impressionnent et qu'on peut se demander si l'argent est bien utilisé, surtout quand on paie beaucoup de cotisations. Cette question est légitime ; la réponse demande de regarder ce que finance cette dépense.",
 legitimes=["La France est effectivement parmi les tout premiers pays pour la dépense sociale en part du PIB.", "Le financement de la protection sociale pèse sur les finances publiques et pose de vrais choix.", "On peut discuter de l'efficacité de certaines dépenses, notamment en santé."],
 contre=[
  ("On dépense des fortunes en aides sociales pour les assistés.", "Selon la Drees, 45,8 % des prestations vont aux retraites et 36,3 % à la santé ; les prestations contre la pauvreté représentent 34 milliards sur 932,5."),
  ("Les autres pays s'en sortent très bien en dépensant moins.", "Selon l'OCDE, en comptant les assurances privées et les avantages fiscaux, les États-Unis passent de la 23e à la 2e place : ils dépensent autant, mais autrement, et de façon plus inégalitaire."),
  ("Tout cet argent ne sert à rien, il y a toujours des pauvres.", "Selon la Drees, les prestations et les impôts font baisser le taux de pauvreté de 21,3 % à 14,4 % : sans eux, des millions de personnes supplémentaires seraient pauvres."),
 ],
 questions=["Si l'on dépensait moins pour les retraites et la santé publiques, qui paierait à la place, et combien ?", "Préfères-tu un système où les soins sont pris en charge collectivement, ou une assurance privée selon tes moyens ?"],
 limites=["Les chiffres de la Drees diffèrent selon le périmètre : 33,6 % du PIB dans les comptes nationaux de la protection sociale, 31,9 % dans la comparaison européenne harmonisée ; ils ne doivent pas être mélangés.", "Le classement de l'OCDE porte sur 2022 et l'article lu date de 2023 ; la page thématique et le rapport « Society at a Glance 2024 » de l'OCDE ont été ouverts, mais leurs chiffres n'ont pas pu être lus.", "Le classement 2024 de la Drees (Finlande devant la France) repose sur des données provisoires.", "L'effet sur la pauvreté porte sur 2022 et ne prend pas en compte l'effet des retraites, des allocations chômage ni des services publics gratuits.", "Les pages ont été lues à travers un outil de lecture qui résume ; les citations sont à revérifier mot pour mot."],
 publics={'convaincus': "Tu as raison, la France est parmi les pays qui dépensent le plus pour le social, la Drees et l'OCDE le confirment. Mais regarde où va l'argent : plus de 80 % finance les retraites et la santé, y compris les tiennes et celles de tes parents. Aux États-Unis, on paie autant en assurances privées, sauf que ceux qui n'ont pas les moyens restent sans soins.",
  'indecis': "La question du coût est légitime : près d'un tiers de la richesse nationale, c'est beaucoup. Mais cet argent paie d'abord les retraites et les soins, et il réduit la pauvreté d'environ 7 points selon la Drees. Les pays qui dépensent moins en public dépensent souvent plus en privé, avec moins de protection pour les plus modestes."},
 a_actualiser='2027-12-31', raison="Nouvelle édition du panorama « La protection sociale en France et en Europe » de la Drees et nouvelles données SOCX de l'OCDE.",
))


# ══ Lot D (25 novembre 2026) ══
