# 1 ── « Les fonctionnaires sont bien plus souvent malades que les salariés du privé » ──────────────
D_ABS_DGAFP26 = ('d_abs_dgafp26', src("Temps et organisation du temps de travail dans la fonction publique en 2025 (Vue Rapport annuel, édition 2026)", "DGAFP (ministère de la Fonction publique)", '15 octobre 2026',
  'https://www.fonction-publique.gouv.fr/toutes-les-publications/le-temps-et-organisation-du-temps-de-travail-dans-la-fonction-publique-en-2025',
  "« Les absences pour raison de santé s’élèvent en 2025 à 11,0 jours en moyenne par agent », soit 0,5 jour de plus que pour les salariés du privé. Par versant : 14,3 jours dans la fonction publique hospitalière, 12,7 jours dans la territoriale, 9,0 jours pour le personnel non enseignant de l'État et 8,1 jours pour les enseignants. La part des agents absents au moins un jour pendant une semaine de référence est de 6 % dans l'hospitalière et la territoriale, 4 % dans celle de l'État. Les femmes et les agents de 50 ans ou plus sont davantage absents.",
  "Publication statistique officielle de la direction générale de l'administration et de la fonction publique (page lue à travers un outil de lecture qui résume).", 'primaire'))
D_ABS_DGAFP25 = ('d_abs_dgafp25', src("Temps et organisation du temps de travail (Vue Rapport annuel 2025, données 2024)", "DGAFP (ministère de la Fonction publique)", '2025',
  'https://www.fonction-publique.gouv.fr/files/files/publications/vue-rapport-annuel/ra_2025_vue_temps_organisation_temps_travail.pdf',
  "Données de l'enquête Emploi de l'Insee (2024). « 5% des agents ont déclaré avoir été absents au moins un jour pour raison de santé durant la semaine de référence », une proportion proche de celle du privé (5 %). « Les agents de la fonction publique se sont absentés 11,1 jours en moyenne en 2024 », contre 10,6 jours dans le privé. Femmes : 12,4 jours dans la fonction publique contre 8,7 pour les hommes ; dans le privé 11,5 et 9,8. 50 ans ou plus : 15,0 jours dans la fonction publique, 13,7 dans le privé. L'écart avec le privé s'explique en partie par des effets de structure (plus de femmes et d'agents âgés) et par la pénibilité de certains métiers. Rupture de série en 2021 (refonte de l'enquête Emploi).",
  "Rapport annuel officiel sur l'état de la fonction publique (PDF lu à travers un outil de lecture qui résume).", 'primaire'))
