FICHES.append(fiche(
 id='rn-retraites-capitalisation', affirmation="Le Rassemblement national veut introduire de la capitalisation dans le système de retraites.", volet='politique', sous_theme='Rassemblement national',
 mots_cles=['rn capitalisation retraites', 'marine le pen capitalisation obligatoire', 'pilier de capitalisation rn', 'reforme des retraites rn 2026', 'rn fonds de pension', 'le pen retraite 60 62 ans', 'rn 1 % logement retraites', 'fonds 900 milliards retraites', 'programme rn retraites 2027', 'le rn veut privatiser les retraites'],
 verdict='confirme', fiabilite='etabli',
 resume="Exact. Le 17 novembre 2026, Marine Le Pen a présenté une réforme des retraites qui ajoute à la répartition un « pilier de capitalisation » obligatoire et universel pour les actifs de moins de 52 ans, géré par la Caisse des dépôts. Il serait financé en réorientant environ 12 milliards d'euros par an de cotisations aujourd'hui consacrées au logement et à la formation professionnelle, selon la presse qui rapporte le projet. C'est une nouveauté par rapport à ses programmes précédents.",
 contexte="Le RN s'est longtemps présenté comme le défenseur de la retraite à 60 ans et du système par répartition. À cinq mois de la présidentielle de 2027, son projet combine un départ entre 60 et 62 ans selon l'âge d'entrée dans la vie active et une part de capitalisation obligatoire.",
 explication="On s'appuie sur la presse qui a rendu compte de la conférence de presse du RN (Public Sénat, LCP, Euronews), on compare au programme de 2022, et on replace le débat dans les projections du Conseil d'orientation des retraites.",
 sources=[D_RN_PS, D_RN_LCP, D_RN_EURONEWS, D_RN_CRIT, D_RN_2022, D_RN_COR],
 faits=[
  fait("Selon Public Sénat, Marine Le Pen a présenté le 17 novembre 2026 un second pilier par capitalisation, « obligatoire et universel », qui s'ajouterait à la répartition et concernerait d'abord les actifs de 52 ans au maximum, avec l'objectif d'un fonds d'environ 900 milliards d'euros « en une génération ».", 'd_rn_ps', '2026', 'France', "L'affirmation est exacte : la capitalisation est au cœur du nouveau projet du RN.", 'etabli', '900 Md€'),
  fait("Selon LCP, le RN prévoit environ 500 euros versés par an sur un compte de capitalisation par salarié ou fonctionnaire, sans prélèvement supplémentaire, pour un complément moyen annoncé de 340 euros par mois ; ce pilier est absent des précédents programmes présidentiels de la candidate.", 'd_rn_lcp', '2026', 'France', "C'est un tournant pour un parti qui se présentait comme défenseur de la seule répartition ; les montants sont des promesses du parti.", 'etabli', '500 €/an'),
  fait("Selon LCP et Euronews, ce fonds serait alimenté par environ 12 milliards d'euros par an de cotisations réorientées (1 % logement, Fonds national d'aide au logement, moitié des cotisations de formation professionnelle), géré par la Caisse des dépôts, avec un rendement annuel estimé par le parti entre 4 % et 6 %.", 'd_rn_euronews', '2026', 'France', "La capitalisation n'est pas gratuite : elle prend l'argent du logement et de la formation des salariés, et son rendement dépend des marchés.", 'estimation', '12 Md€/an'),
  fait("Selon Public Sénat, le projet prévoit aussi un départ entre 60 et 62 ans selon cinq paliers, de 40 annuités pour ceux qui ont commencé avant 20 ans à 42 pour ceux entrés après 23 ans, une décote portée à 5 % par trimestre manquant et la validation d'un trimestre conditionnée à au moins un mi-temps.", 'd_rn_ps', '2026', 'France', "La « retraite à 60 ans » ne concerne que ceux qui ont commencé tôt ; d'autres règles se durcissent, au détriment des carrières hachées.", 'etabli', '60-62 ans'),
  fait("Selon Public Sénat, en 2022 Marine Le Pen avait déjà abandonné la retraite à 60 ans pour tous au profit d'un système progressif : taux plein à 60 ans après 40 annuités pour ceux entrés entre 17 et 20 ans, au moins 42 annuités pour ceux entrés à partir de 25 ans ; le programme ne comportait pas de pilier de capitalisation.", 'd_rn_2022', '2022', 'France', "La logique d'âge selon l'entrée dans la vie active est reprise ; la capitalisation est la grande nouveauté de 2026.", 'etabli', '40 annuités'),
  fait("Selon le COR, le système de retraite serait déficitaire de 5,1 milliards d'euros en 2025, soit -0,2 % du PIB, et de -0,9 % du PIB en 2045 dans le scénario de référence, pour des dépenses de 14,1 % du PIB.", 'd_rn_cor', '2025-2070', 'France', "Le besoin de financement existe, mais il reste limité à moyen terme : il ne justifie pas en soi de basculer vers les marchés financiers.", 'etabli', '-0,2 % du PIB'),
  fait("Fait défavorable : selon les articles de presse, Marine Le Pen se dit attachée à la répartition, la capitalisation proposée resterait un complément géré par un organisme public, la Caisse des dépôts, et le projet ne crée pas de nouveau prélèvement selon le parti.", 'd_rn_lcp', '2026', 'France', "Il ne s'agit pas de remplacer la répartition, mais d'y ajouter une part de capitalisation : c'est ce que dit l'affirmation, sans exagération possible.", 'interpretation'),
 ],
 court="C'est exact. Le 17 novembre 2026, Marine Le Pen a présenté un « pilier de capitalisation » obligatoire et universel, ajouté à la répartition, alimenté par environ 12 milliards d'euros par an pris sur les cotisations du logement et de la formation professionnelle, selon Public Sénat, LCP et Euronews. C'est une nouveauté par rapport à ses programmes précédents.",
 moyen="Oui, le RN propose bien d'introduire de la capitalisation. Selon la presse qui a rendu compte de sa conférence de presse du 17 novembre 2026, Marine Le Pen veut créer un second pilier « obligatoire et universel », à côté de la répartition, pour les actifs de moins de 52 ans. Le parti annonce environ 500 euros versés par an sur un compte individuel, géré par la Caisse des dépôts, et un fonds de 900 milliards d'euros en une génération.\n\nCet argent ne tombe pas du ciel : il viendrait de cotisations qui financent aujourd'hui le logement des salariés et la formation professionnelle, pour environ 12 milliards d'euros par an. Et le rendement promis, de 4 à 6 % par an selon le RN, dépend des marchés financiers. Ce pilier ne figurait pas dans les programmes présidentiels précédents de Marine Le Pen.",
 detaille="L'affirmation est exacte. Le 17 novembre 2026, au siège du RN, Marine Le Pen a présenté sa réforme des retraites pour la présidentielle de 2027. Selon Public Sénat, LCP et Euronews, elle comprend deux volets.\n\nLe premier concerne l'âge : départ entre 60 et 62 ans selon cinq paliers liés à l'âge du premier emploi stable, 40 annuités pour ceux qui ont commencé avant 20 ans, 42 pour ceux entrés après 23 ans, abrogation de la réforme Borne au 1er janvier 2028. En contrepartie, la décote serait durcie (5 % par trimestre manquant) et il faudrait au moins un mi-temps pour valider un trimestre, ce qui pénaliserait les carrières hachées. Cette logique reprend celle du programme de 2022, qui avait déjà abandonné la retraite à 60 ans pour tous.\n\nLe second volet est nouveau : un « pilier de capitalisation » obligatoire et universel, s'ajoutant à la répartition, pour les actifs de moins de 52 ans. Selon le parti, environ 500 euros seraient versés chaque année sur un compte individuel, pour un complément moyen de 340 euros par mois. Le fonds, géré par la Caisse des dépôts, serait alimenté par environ 12 milliards d'euros par an pris sur le 1 % logement, le Fonds national d'aide au logement et la moitié des cotisations de formation professionnelle, et par le Fonds de réserve pour les retraites. Le rendement espéré, entre 4 et 6 % par an, est une estimation du parti.\n\nMême à droite, des responsables comme Bruno Retailleau dénoncent un « transfert de charges » : « Il faudra bien que quelqu'un paie à la place ». Or le Conseil d'orientation des retraites chiffre le déficit du système à 5,1 milliards d'euros en 2025, soit 0,2 % du PIB : un besoin réel mais limité, qui peut être financé par des ressources nouvelles plutôt que par un pari sur les marchés financiers. La capitalisation transfère les risques sur les salariés et fait dépendre une partie des pensions de la Bourse : c'est un choix politique qu'il faut nommer comme tel.",
 empathie="Beaucoup de gens se méfient de l'avenir du système et trouvent rassurant d'avoir un capital à leur nom. Cette inquiétude est légitime ; la question est de savoir qui paie ce capital et qui porte le risque.",
 legitimes=["Le RN maintient la répartition comme socle et présente la capitalisation comme un complément.", "Le fonds serait géré par la Caisse des dépôts, un organisme public, et non par des fonds de pension privés.", "Le système de retraite connaît un déficit et des besoins de financement à long terme, selon le COR."],
 contre=[
  ("Le RN défend la retraite à 60 ans, il n'a rien d'un libéral.", "La retraite à 60 ans ne vaudrait que pour ceux qui ont commencé avant 20 ans ; et le projet ajoute un pilier de capitalisation obligatoire, une idée longtemps portée par la droite libérale."),
  ("Ce n'est pas de la capitalisation privée, c'est la Caisse des dépôts.", "Le gestionnaire est public, mais le principe reste la capitalisation : des comptes individuels dont le montant dépend du rendement des placements, estimé par le RN lui-même entre 4 et 6 % par an."),
  ("Ça ne coûte rien, il n'y a pas de nouveau prélèvement.", "Les 12 milliards d'euros par an viendraient de cotisations qui financent aujourd'hui le logement des salariés et la formation professionnelle : ce sont ces politiques qui en paieraient le prix."),
 ],
 questions=["Si l'argent du fonds vient du logement et de la formation des salariés, qui paiera ces politiques demain ?", "Que deviendrait le complément de pension promis si les marchés financiers chutaient l'année de ton départ ?"],
 limites=["L'article de franceinfo indiqué (« Age de départ, part de capitalisation, possible référendum… ») n'a pas pu être ouvert : le site bloque l'outil de lecture. Les propositions sont attribuées à Public Sénat, LCP et Euronews.", "Tous les articles ont été lus à travers un outil de lecture qui résume ; les citations sont à revérifier mot pour mot.", "Les montants (500 euros par an, 340 euros par mois, 900 milliards, rendement de 4 à 6 %) sont des chiffrages du RN, non vérifiés de façon indépendante ; les articles divergent sur le coût net annoncé.", "Aucune analyse du COR spécifique au projet du RN ni à la capitalisation n'a été lue ; seule la synthèse du rapport annuel de juin 2026 l'a été.", "Le projet peut évoluer d'ici l'élection présidentielle ; des divergences internes au RN sur les retraites ont été rapportées par la presse sans être vérifiées ici."],
 publics={'convaincus': "Tu peux vérifier : c'est Marine Le Pen elle-même qui a présenté le 17 novembre un « pilier de capitalisation » obligatoire, qu'elle qualifie de « vraie révolution ». L'argent viendrait des cotisations du logement et de la formation des salariés. Ce n'est pas une attaque contre le RN, c'est son propre projet : la question est de savoir si tu veux qu'une partie de ta retraite dépende de la Bourse.",
  'indecis': "C'est rassurant, sur le papier, d'avoir un capital à son nom. Mais selon le projet présenté par le RN, ce capital serait financé en prenant environ 12 milliards d'euros par an au logement et à la formation professionnelle, et son rendement dépendrait des marchés. Le COR chiffre le déficit actuel du système à 0,2 % du PIB : d'autres solutions existent pour le financer."},
 a_actualiser='2027-04-30', raison="Publication du programme présidentiel définitif du RN et éventuels chiffrages indépendants.",
))

# 3 ── « De plus en plus de Français sont payés au Smic, le Smic devient le salaire de la majorité » ──────────────
D_SMIC_MV = ('d_smic_mv', src("Smic : qui sont les salariés qui touchent le salaire minimum en 2026 ? Les résultats de l'étude de la Dares", 'MoneyVox, d\'après la Dares', '15 octobre 2026',
  'https://www.moneyvox.fr/votre-argent/actualites/110844/smic-qui-sont-les-salaries-qui-touchent-le-salaire-minimum-en-2026-les-resultats-de-etude-de-la-dares',
  "Selon la Dares, 11,8 % des salariés du privé non agricole, environ 2,1 millions de personnes, ont été directement concernés par la revalorisation de 1,2 % du Smic (12,02 euros brut de l'heure) au 1er janvier 2026, contre 12,4 % au 1er novembre 2024. 25,6 % des salariés à temps partiel en ont bénéficié contre 8,8 % des temps complets ; près de 60 % des bénéficiaires sont des femmes ; 21,9 % dans les entreprises de 1 à 9 salariés ; 62,3 % dans la restauration rapide.",
  "Article de presse économique résumant la publication de la Dares (lu à travers un outil de lecture qui résume) ; la page de la Dares n'a pas pu être ouverte.", 'secondaire'))
D_SMIC_AFP = ('d_smic_afp', src("Revalorisation du Smic : légère baisse de la part de bénéficiaires au 1er janvier (étude)", "ID, l'Info Durable (dépêche, d'après la Dares)", '15 octobre 2026',
  'https://www.linfodurable.fr/revalorisation-du-smic-legere-baisse-de-la-part-de-beneficiaires-au-1er-janvier-etude-59391',
  "2,1 millions de salariés du privé, soit « 11,8% des salariés (hors secteur agricole) », ont vu leur salaire augmenter directement avec la revalorisation du 1er janvier 2026, en baisse « depuis le pic de 17,3% atteint au 1er janvier 2023 » (12,4 % au 1er novembre 2024). Le Smic est « le seul salaire évoluant mécaniquement avec l'inflation ». Il a de nouveau été revalorisé automatiquement de 2,4 % le 1er juin 2026.",
  "Dépêche reprise par un média (logo AFP affiché), lue à travers un outil de lecture qui résume.", 'secondaire'))
D_SMIC_INSEE = ('d_smic_insee', src("Les salaires dans le secteur privé en 2025 (Insee Première n° 2132)", 'Insee', 'octobre 2026',
  'https://www.insee.fr/fr/statistiques/fichier/9087193/ip2132.pdf',
  "En 2025, salaire mensuel net moyen en équivalent temps plein dans le privé : 2 797 euros ; médian : 2 238 euros ; premier décile : 1 519 euros ; neuvième décile : 4 441 euros. Le Smic net s'établit à 1 426 euros. Le salaire médian est inférieur de 20,0 % au salaire moyen. Le rapport interdécile passe de 2,91 à 2,92.",
  "Publication de la statistique publique (PDF lu à travers un outil de lecture qui résume).", 'primaire'))
D_SMIC_BW = ('d_smic_bw', src("Mission sur l'articulation entre les salaires, le coût du travail et la prime d'activité — rapport d'étape (Antoine Bozio et Étienne Wasmer)", 'France Stratégie (mission Bozio-Wasmer)', 'avril 2024',
  'https://www.strategie.gouv.fr/sites/strategie.gouv.fr/files/atoms/files/rapport_detape_final_-_7_mai_2024.pdf',
  "Coût des allègements généraux de cotisations estimé à 75 milliards d'euros en 2023. « La proportion de personnes rémunérées moins de 1,1 fois le Smic est ainsi passée de 10,6 à 11,6 % entre 1994 et 2006 » et « était de 10,5 % en 2022 » ; la distribution est stable après 2006. En 2021 et 2022, « le dynamisme du Smic sous l'effet du retour d'une inflation forte a contribué à une contraction de la distribution des salaires ». L'inflation « a compressé la distribution des salaires et rendu plus d'emplois éligibles aux exonérations ». Les taux marginaux élevés liés à la sortie des exonérations peuvent freiner les hausses de salaire, mais leur preuve empirique « est néanmoins délicate ».",
  "Rapport d'expertise remis au gouvernement par deux économistes (long PDF lu par parties à travers un outil de lecture qui résume).", 'primaire'))

FICHES.append(fiche(
 id='smic-salaire-majorite', affirmation="De plus en plus de Français sont payés au Smic : le salaire minimum est devenu le salaire de la majorité.", volet='economie', sous_theme='Salaires',
 mots_cles=['tout le monde est au smic', 'smic salaire de la majorite', 'smicardisation', 'de plus en plus de smicards', 'part des salaries au smic', 'tassement des salaires', 'salaire median smic', 'exonerations bas salaires trappe', 'revalorisation smic beneficiaires', 'bientot tous payes au smic'],
 verdict='trompeur', fiabilite='etabli',
 resume="Faux sur la majorité, juste sur le tassement. Selon la Dares, 11,8 % des salariés du privé étaient directement concernés par la hausse du Smic au 1er janvier 2026, après un pic de 17,3 % en 2023. Le salaire médian net (2 238 euros en 2025) reste nettement au-dessus du Smic net (1 426 euros), selon l'Insee. Mais l'inflation a resserré le bas de l'échelle, et les exonérations de cotisations sur les bas salaires peuvent freiner les augmentations.",
 contexte="Le sentiment que « tout le monde finit au Smic » s'est renforcé avec l'inflation de 2022-2023 : le Smic, indexé sur les prix, a augmenté plus vite que beaucoup d'autres salaires. Le mot « smicardisation » est utilisé à droite comme à gauche, avec des remèdes opposés.",
 explication="On distingue la part des salariés directement payés au Smic (Dares), la distribution des salaires (Insee) et le tassement au voisinage du Smic, analysé par le rapport Bozio-Wasmer de 2024.",
 sources=[D_SMIC_MV, D_SMIC_AFP, D_SMIC_INSEE, D_SMIC_BW],
 faits=[
  fait("Selon la Dares, 11,8 % des salariés du privé non agricole, environ 2,1 millions de personnes, ont été directement concernés par la revalorisation du Smic au 1er janvier 2026, contre 12,4 % au 1er novembre 2024.", 'd_smic_mv', '2024-2026', 'France, secteur privé non agricole', "Les salariés au Smic sont une minorité, de l'ordre d'un sur huit.", 'etabli', '11,8 %'),
  fait("Selon la Dares, rapportée par une dépêche, la part de bénéficiaires recule « depuis le pic de 17,3% atteint au 1er janvier 2023 ».", 'd_smic_afp', '2023-2026', 'France, secteur privé non agricole', "La part a bien augmenté pendant la vague d'inflation, puis elle a reflué.", 'etabli', '17,3 %'),
  fait("Selon l'Insee, en 2025, le salaire net médian en équivalent temps plein dans le privé est de 2 238 euros par mois et le salaire moyen de 2 797 euros, pour un Smic net de 1 426 euros ; même le premier décile (1 519 euros) dépasse le Smic.", 'd_smic_insee', '2025', 'France, secteur privé', "La moitié des salariés gagnent plus de 2 238 euros nets : le Smic n'est pas le salaire de la majorité.", 'etabli', '2 238 €'),
  fait("Selon la Dares, 25,6 % des salariés à temps partiel ont bénéficié de la revalorisation de janvier 2026 contre 8,8 % des temps complets ; près de 60 % des bénéficiaires sont des femmes, et la part atteint 62,3 % dans la restauration rapide.", 'd_smic_mv', '2026', 'France, secteur privé non agricole', "Le Smic concerne d'abord les femmes, le temps partiel et certains secteurs : c'est là que se concentre la précarité salariale.", 'etabli', '25,6 %'),
  fait("Selon le rapport Bozio-Wasmer, la part des salariés payés moins de 1,1 Smic est passée de 10,6 % à 11,6 % entre 1994 et 2006, puis était de 10,5 % en 2022 ; en 2021 et 2022, la hausse du Smic sous l'effet de l'inflation a contribué à une contraction de la distribution des salaires.", 'd_smic_bw', '1994-2022', 'France', "Le tassement est réel, surtout en période d'inflation, même si la part des salariés au voisinage du Smic n'a pas explosé.", 'etabli', '10,5 %'),
  fait("Selon le même rapport, les allègements généraux de cotisations ont coûté environ 75 milliards d'euros en 2023 ; leur caractère dégressif crée des taux marginaux élevés qui peuvent freiner les hausses de salaire, même si la preuve empirique de cette « trappe » est jugée délicate.", 'd_smic_bw', '2023', 'France', "Des aides publiques massives aux bas salaires peuvent inciter à maintenir les rémunérations près du Smic.", 'debat', '75 Md€'),
  fait("Fait défavorable : selon la Dares, plus d'un salarié sur six était directement concerné par la hausse du Smic au 1er janvier 2023 (17,3 %), et 2,5 % des salariés restaient couverts par des grilles de branche inférieures au Smic à la veille du 1er janvier 2026.", 'd_smic_mv', '2023-2026', 'France, secteur privé non agricole', "Le ressenti de déclassement repose sur une réalité : des grilles de salaires qui ne suivent pas et des débuts de carrière proches du Smic.", 'etabli', '2,5 %'),
 ],
 court="Non, le Smic n'est pas le salaire de la majorité : 11,8 % des salariés du privé étaient concernés par sa hausse en janvier 2026, selon la Dares, et le salaire médian net (2 238 euros) dépasse nettement le Smic net (1 426 euros), selon l'Insee. Mais l'inflation a tassé le bas de l'échelle, et la part au Smic a culminé à 17,3 % en 2023.",
 moyen="Le Smic n'est pas devenu le salaire de la majorité. Selon la Dares, 11,8 % des salariés du privé, environ 2,1 millions de personnes, ont été directement concernés par sa revalorisation au 1er janvier 2026. Selon l'Insee, la moitié des salariés du privé gagnent plus de 2 238 euros nets par mois en équivalent temps plein, contre 1 426 euros pour le Smic net.\n\nLe sentiment de « smicardisation » n'est pourtant pas sans fondement. Pendant la vague d'inflation, le Smic, indexé sur les prix, a rattrapé des salaires qui stagnaient : la part de salariés concernés a culminé à 17,3 % en 2023. Et les exonérations de cotisations, environ 75 milliards d'euros en 2023 selon le rapport Bozio-Wasmer, peuvent inciter les employeurs à maintenir les salaires près du Smic. Le vrai sujet, c'est donc le blocage des salaires juste au-dessus.",
 detaille="L'affirmation mélange un ressenti juste et un chiffre faux. Le chiffre faux d'abord : selon la Dares, 11,8 % des salariés du privé non agricole, soit environ 2,1 millions de personnes, ont été directement concernés par la revalorisation du Smic au 1er janvier 2026. C'est moins qu'au 1er novembre 2024 (12,4 %) et nettement moins qu'au pic de janvier 2023 (17,3 %). Selon l'Insee, le salaire net médian en équivalent temps plein dans le privé atteint 2 238 euros en 2025, contre 1 426 euros pour le Smic net : la majorité des salariés n'est pas au Smic.\n\nLe ressenti juste ensuite. Pendant l'inflation de 2021-2023, le Smic, seul salaire indexé automatiquement sur les prix, a augmenté plus vite que les salaires qui le suivaient. Le rapport Bozio-Wasmer note que cette dynamique a « contribué à une contraction de la distribution des salaires ». Beaucoup de salariés ont vu leur écart avec le Smic fondre, et des grilles de branche sont même passées sous le salaire minimum : 2,5 % des salariés étaient encore concernés à la veille de janvier 2026.\n\nLes salariés au Smic sont d'abord des femmes (près de 60 % des bénéficiaires), des temps partiels (25,6 % d'entre eux sont concernés) et des salariés de très petites entreprises ou de secteurs comme la restauration rapide.\n\nEnfin, les allègements de cotisations sur les bas salaires ont coûté environ 75 milliards d'euros en 2023. Comme ils diminuent quand le salaire augmente, ils rendent chaque hausse plus coûteuse pour l'employeur. Les auteurs jugent la preuve empirique de cette « trappe » délicate, mais le risque est sérieux. La réponse n'est pas d'opposer smicards et salariés modestes, mais d'augmenter les salaires, de conditionner les aides publiques et de rouvrir les négociations de branche.",
 empathie="Quand on a dix ans d'ancienneté et qu'on gagne à peine plus qu'un nouvel embauché au Smic, on a le sentiment d'être déclassé, et ce sentiment est fondé. Le problème n'est pas le Smic, c'est que les salaires juste au-dessus n'ont pas suivi.",
 legitimes=["La part de salariés concernés par les hausses du Smic a nettement augmenté pendant la période d'inflation, jusqu'à 17,3 % en 2023.", "Les salaires proches du Smic se sont tassés, et des grilles de branche sont passées sous le salaire minimum.", "Les exonérations de cotisations dégressives peuvent freiner les augmentations au-dessus du Smic."],
 contre=[
  ("Tout le monde autour de moi est au Smic.", "Dans certains secteurs, c'est presque vrai : 62,3 % des salariés de la restauration rapide étaient concernés en janvier 2026. Mais sur l'ensemble du privé, c'est 11,8 %, et le salaire médian dépasse 2 200 euros nets."),
  ("Si le Smic augmente, tout le monde finira au Smic.", "Le tassement vient surtout de salaires au-dessus qui ne suivent pas. La solution est de relever l'ensemble des grilles et de conditionner les exonérations, pas de bloquer le Smic."),
  ("C'est à cause des charges trop lourdes que les salaires ne montent pas.", "Les cotisations sur les bas salaires sont déjà massivement allégées, pour environ 75 milliards d'euros en 2023 ; ce sont justement ces allègements dégressifs qui peuvent freiner les hausses."),
 ],
 questions=["Si la moitié des salariés du privé gagnent plus de 2 238 euros nets, le problème est-il le nombre de smicards ou le blocage des salaires juste au-dessus ?", "Est-il normal que l'État paie environ 75 milliards d'euros d'allègements sans exiger de hausses de salaires en échange ?"],
 limites=["La publication de la Dares n'a pas pu être ouverte (page de vérification anti-robots) : ses chiffres sont repris de deux articles de presse qui la résument.", "Les documents ont été lus à travers un outil de lecture qui résume ; les citations sont à revérifier mot pour mot.", "Le salaire médian de l'Insee est calculé en équivalent temps plein : il ne reflète pas les revenus des salariés à temps partiel.", "La part des salariés au voisinage du Smic issue du rapport Bozio-Wasmer porte sur 2022 ; aucun chiffre plus récent n'a été lu.", "Le rapport final de la mission Bozio-Wasmer (octobre 2024) n'a pas pu être ouvert ; seul le rapport d'étape l'a été."],
 publics={'convaincus': "Tu as raison de dire que beaucoup de salaires se rapprochent du Smic, le rapport Bozio-Wasmer le confirme pour la période d'inflation. Mais selon la Dares, c'est environ un salarié du privé sur huit qui est au Smic, pas la majorité. Le vrai scandale, c'est que des patrons touchent des milliards d'allègements pour des bas salaires sans obligation d'augmenter les gens.",
  'indecis': "Le sentiment d'être payé « presque au Smic » après des années de travail est réel et légitime. Les chiffres disent que 11,8 % des salariés du privé étaient concernés par la hausse de janvier 2026, et que le salaire médian est autour de 2 240 euros nets. Ce qu'il faut regarder, ce sont les grilles salariales et les exonérations qui freinent les augmentations au-dessus du Smic."},
 a_actualiser='2027-10-31', raison="Nouvelle étude de la Dares sur la revalorisation du Smic au 1er janvier 2027 et Insee Première sur les salaires du privé en 2026.",
))

# 4 ── « L'ouverture des magasins le dimanche crée des emplois » ──────────────
D_DIM_INSEE = ('d_dim_insee', src("Qui travaillera dimanche ? Les gagnants et les perdants de la déréglementation du travail dominical (document de travail n° 2023-02)", 'Insee (Dominique Goux et Éric Maurin)', '26 janvier 2023',
  'https://www.insee.fr/fr/statistiques/6792865',
  "Depuis 2016, l'ouverture dominicale du commerce de détail est autorisée dans « une trentaine de zones du territoire métropolitain, représentant en tout environ 3 % du commerce de détail en France ». La réforme ne s'est accompagnée d'« aucune hausse des effectifs ou du chiffre d'affaires » dans le commerce de détail des zones ciblées : les magasins ouvrent un jour de plus mais les effectifs restent à peu près stables. Les employeurs ont privilégié des salariés expérimentés ; la part des salariés peu expérimentés baisse nettement et l'emploi des parents isolés chute fortement.",
  "Document de travail de chercheurs de l'Insee et de l'EHESS (résumé de la page lu à travers un outil de lecture ; le texte intégral en PDF n'a pas pu être ouvert).", 'primaire'))
D_DIM_AN = ('d_dim_an', src("Rapport d'information de la mission d'information commune sur l'évaluation de la loi n° 2015-990 du 6 août 2015 (tome II, comptes rendus)", 'Assemblée nationale', '29 novembre 2018',
  'https://questions.assemblee-nationale.fr/dyn/15/rapports/micmacron/l15b1454-tii_rapport-information.pdf',
  "Les rapporteurs regrettent de « ne pas disposer d'études statistiques permettant d'évaluer les retombées en termes d'emplois créés ». Les taux d'ouverture dans les périmètres concernés varient « entre 8 % et 80 % des établissements concernés ». « S'il n'y a pas de clients potentiels, il n'y aura pas d'ouverture dominicale » ; des boutiques de la place Vendôme ont renoncé, leur chiffre d'affaires ne couvrant pas les compensations. Les compensations négociées ont parfois atteint « un triplement du salaire ».",
  "Document parlementaire officiel (comptes rendus, lu à travers un outil de lecture qui résume ; le tome I n'a pas été ouvert).", 'primaire'))
D_DIM_BDT = ('d_dim_bdt', src("Loi Macron : trois ans après, un bilan en demi-teinte", 'Banque des Territoires (Localtis)', '4 décembre 2018',
  'https://www.banquedesterritoires.fr/loi-macron-trois-ans-apres-un-bilan-en-demi-teinte',
  "Selon la mission d'information présidée par Yves Blein, le maintien et l'élargissement du travail dominical dans les zones touristiques internationales ont permis un développement notable du chiffre d'affaires et de l'emploi, mais « les données en ce domaine demeurent imprécises ». À Paris, 28,2 % des commerces situés en zone touristique internationale ouvrent le dimanche, contre 17,5 % avant la loi. Bilan plus mitigé en région ; les petits commerces doivent compenser le travail dominical de leurs salariés.",
  "Média des collectivités résumant le rapport parlementaire (lu à travers un outil de lecture qui résume).", 'secondaire'))
D_DIM_OFCE = ('d_dim_ofce', src("Jamais le dimanche ?", 'OFCE (Sciences Po), Xavier Timbeau', '10 juin 2008',
  'https://ofce.sciences-po.fr/blog/jamais-le-dimanche/?print=pdf',
  "« Ouvrir un jour de plus apporte plus d'activité uniquement si les concurrents sont fermés au même moment. » Les consommateurs ne dépensent pas davantage parce qu'ils peuvent acheter le dimanche, leur revenu restant décisif. Après l'assouplissement allemand de 2003, valeur ajoutée, emploi et masse salariale du commerce de détail ont suivi une trajectoire inchangée. « Ouvrir plus longtemps ne fait pas consommer plus. »",
  "Billet d'un économiste d'un centre de recherche universitaire (lu à travers un outil de lecture qui résume) ; texte ancien.", 'secondaire'))
D_DIM_DARES = ('d_dim_dares', src("Près d'un Français sur quatre concerné par le travail le dimanche", 'Banque des Territoires (Localtis), d\'après la Dares', '5 juin 2026',
  'https://www.banquedesterritoires.fr/pres-dun-francais-sur-quatre-concerne-par-le-travail-le-dimanche',
  "Selon la Dares, en 2025, « 23,2% des personnes en emploi ont travaillé au moins un dimanche sur une période de quatre semaines consécutives », un point de moins qu'en 2024 et sous le niveau de 2019 (25,8 %) ; 20,7 % des salariés et près de 40 % des indépendants. Hébergement-restauration : 47,3 %.",
  "Média des collectivités résumant une étude de la Dares (lu à travers un outil de lecture qui résume) ; l'étude de la Dares n'a pas été ouverte.", 'secondaire'))

FICHES.append(fiche(
 id='ouverture-dimanche-emplois', affirmation="Ouvrir les magasins le dimanche crée des emplois.", volet='droits', sous_theme='Droits des travailleurs',
 mots_cles=['travail du dimanche cree des emplois', 'ouverture dominicale emplois', 'magasins ouverts le dimanche', 'loi macron travail dominical', 'zones touristiques internationales', 'travail dominical commerce', 'ouvrir le dimanche relance consommation', 'dimanche jour de repos', 'volontariat travail du dimanche', 'deregulation travail dominical'],
 verdict='contredit', fiabilite='estimation',
 resume="Les évaluations ne le montrent pas. Selon une étude de chercheurs de l'Insee, l'ouverture dominicale autorisée depuis 2016 dans une trentaine de zones n'a entraîné « aucune hausse des effectifs ou du chiffre d'affaires » du commerce de détail : les magasins ouvrent un jour de plus avec à peu près autant de salariés. Les parents isolés et les salariés débutants en ont même pâti. Les députés chargés d'évaluer la loi Macron regrettaient en 2018 l'absence d'études chiffrant les emplois créés.",
 contexte="La loi Macron du 6 août 2015 a créé des zones touristiques internationales où les commerces peuvent ouvrir tous les dimanches, et assoupli le travail dominical ailleurs. L'argument de l'emploi revient à chaque débat sur l'extension de l'ouverture dominicale.",
 explication="On s'appuie sur l'évaluation statistique de l'Insee (Goux et Maurin), sur la mission d'évaluation de l'Assemblée nationale (2018), sur une analyse de l'OFCE et sur les chiffres de la Dares sur le travail du dimanche.",
 sources=[D_DIM_INSEE, D_DIM_AN, D_DIM_BDT, D_DIM_OFCE, D_DIM_DARES],
 faits=[
  fait("Selon un document de travail de l'Insee (Goux et Maurin, 2023), l'ouverture dominicale autorisée depuis 2016 dans une trentaine de zones, environ 3 % du commerce de détail, ne s'est accompagnée d'« aucune hausse des effectifs ou du chiffre d'affaires » dans les zones ciblées.", 'd_dim_insee', '2016-2023', 'France métropolitaine', "Les magasins ouvrent un jour de plus avec à peu près les mêmes équipes : le travail est réparti autrement, pas multiplié.", 'estimation', '3 %'),
  fait("Selon la même étude, les employeurs ont privilégié des salariés expérimentés capables de tenir seuls un magasin ; la part des salariés peu expérimentés a nettement baissé et l'emploi des parents isolés a fortement chuté dans les zones concernées.", 'd_dim_insee', '2016-2023', 'France métropolitaine', "La déréglementation a des perdants : ceux qui ne peuvent pas laisser leurs enfants le dimanche.", 'estimation'),
  fait("Selon le rapport de la mission d'évaluation de la loi Macron à l'Assemblée nationale (2018), les rapporteurs regrettaient de « ne pas disposer d'études statistiques permettant d'évaluer les retombées en termes d'emplois créés ».", 'd_dim_an', '2015-2018', 'France', "Les promesses d'emploi de la loi n'ont jamais été chiffrées par les pouvoirs publics.", 'etabli'),
  fait("Selon le même rapport, les taux d'ouverture dominicale varient de 8 % à 80 % des établissements selon les périmètres, et certaines boutiques de la place Vendôme y ont renoncé parce que leur chiffre d'affaires ne couvrait pas les compensations versées aux salariés.", 'd_dim_an', '2015-2018', 'France', "Sans clients supplémentaires, ouvrir le dimanche ne rapporte pas : les ventes sont surtout déplacées d'un jour à l'autre.", 'etabli', '8 à 80 %'),
  fait("Selon un économiste de l'OFCE (2008), ouvrir un jour de plus n'apporte de l'activité que si les concurrents sont fermés ; après l'assouplissement allemand de 2003, emploi et valeur ajoutée du commerce de détail ont suivi une trajectoire inchangée.", 'd_dim_ofce', '2003-2008', 'Allemagne', "Le pouvoir d'achat ne grandit pas parce que les magasins ouvrent plus longtemps : l'argent dépensé le dimanche ne l'est pas un autre jour.", 'interpretation'),
  fait("Selon la Dares, citée par la Banque des Territoires, 23,2 % des personnes en emploi ont travaillé au moins un dimanche sur quatre semaines en 2025, contre 25,8 % en 2019 ; la part atteint 47,3 % dans l'hébergement-restauration.", 'd_dim_dares', '2019-2025', 'France', "Le travail du dimanche concerne déjà près d'un actif sur quatre.", 'etabli', '23,2 %'),
  fait("Fait défavorable : selon la Banque des Territoires résumant la mission parlementaire de 2018, le travail dominical dans les zones touristiques internationales a permis un développement notable du chiffre d'affaires et de l'emploi, et à Paris 28,2 % des commerces de ces zones ouvrent le dimanche contre 17,5 % avant la loi ; mais les données « demeurent imprécises ».", 'd_dim_bdt', '2015-2018', 'Paris', "Des enseignes ont pu embaucher localement, surtout dans les grands magasins touristiques ; mais une hausse dans un quartier peut se faire au détriment d'autres commerces, et l'étude de l'Insee ne trouve pas d'effet sur les effectifs.", 'interpretation', '28,2 %'),
 ],
 court="Les évaluations ne trouvent pas cet effet. Selon des chercheurs de l'Insee, l'ouverture dominicale autorisée depuis 2016 dans une trentaine de zones n'a entraîné « aucune hausse des effectifs ou du chiffre d'affaires » du commerce de détail. Les magasins ouvrent un jour de plus avec à peu près autant de salariés, et l'emploi des parents isolés a fortement chuté.",
 moyen="L'idée paraît logique : un jour d'ouverture en plus, il faut plus de vendeurs. Mais l'évaluation la plus solide disponible, menée par des chercheurs de l'Insee, ne trouve « aucune hausse des effectifs ou du chiffre d'affaires » dans les zones où l'ouverture dominicale est autorisée depuis 2016. Les magasins ont réorganisé leurs équipes plutôt qu'embauché.\n\nLa raison est simple : les ménages ne dépensent pas plus parce que les magasins ouvrent plus longtemps, leur budget dépend de leur revenu. Les achats du dimanche sont surtout pris sur les autres jours. En revanche, il y a des perdants : selon la même étude, l'emploi des parents isolés a fortement chuté dans ces zones. Les députés chargés d'évaluer la loi Macron regrettaient d'ailleurs en 2018 de ne disposer d'aucune étude chiffrant les emplois créés.",
 detaille="La loi Macron du 6 août 2015 a créé des zones touristiques internationales où les commerces peuvent ouvrir tous les dimanches, au nom de l'emploi et de l'attractivité. Dix ans plus tard, les évaluations disponibles ne confirment pas cette promesse.\n\nEn 2018, la mission d'évaluation de l'Assemblée nationale regrettait de « ne pas disposer d'études statistiques permettant d'évaluer les retombées en termes d'emplois créés ». Elle relevait des taux d'ouverture très variables, de 8 % à 80 % des établissements, et notait que sans clients supplémentaires il n'y a pas d'ouverture : des boutiques de la place Vendôme ont renoncé, faute de chiffre d'affaires suffisant pour payer les compensations. Les enseignes parisiennes faisaient état de gains, mais les députés reconnaissaient que les données restaient imprécises.\n\nEn 2023, Dominique Goux et Éric Maurin ont publié à l'Insee une évaluation statistique sur une trentaine de zones, environ 3 % du commerce de détail. Leur résultat : « aucune hausse des effectifs ou du chiffre d'affaires ». Les magasins ouvrent un jour de plus avec des équipes à peu près stables. Les employeurs privilégient des salariés expérimentés capables de tenir seuls un magasin ; la part des débutants baisse, et l'emploi des parents isolés chute fortement.\n\nCe résultat rejoint un raisonnement économique ancien, rappelé par l'OFCE : un jour d'ouverture de plus n'apporte de l'activité que si les concurrents restent fermés, et les ménages ne dépensent pas plus parce que les magasins ouvrent plus longtemps. L'Allemagne n'a pas vu son emploi dans le commerce changer après son assouplissement de 2003.\n\nLe travail du dimanche concerne déjà près d'un actif sur quatre selon la Dares. Le repos dominical commun est un acquis social : il permet la vie de famille, associative et collective. L'étendre au nom d'emplois qui n'apparaissent pas dans les évaluations revient à demander des sacrifices aux salariés, souvent les plus fragiles, sans contrepartie pour l'emploi.",
 empathie="On peut apprécier de faire ses courses le dimanche, et certains salariés sont contents des majorations. Mais il faut distinguer le confort du client et la promesse d'emplois, que les études ne confirment pas.",
 legitimes=["Certaines enseignes des zones très touristiques déclarent des gains de chiffre d'affaires le dimanche.", "Des salariés volontaires apprécient les majorations de salaire liées au travail dominical.", "Une seule étude statistique solide ne clôt pas définitivement le débat."],
 contre=[
  ("Il faut bien des vendeurs en plus pour ouvrir un jour de plus.", "Selon l'étude de l'Insee, les effectifs sont restés à peu près stables : les magasins ont réorganisé les plannings et privilégié des salariés expérimentés, plutôt que d'embaucher."),
  ("Les Galeries Lafayette disent avoir embauché.", "Des gains locaux dans les grands magasins touristiques sont possibles, mais les députés eux-mêmes jugeaient les données imprécises, et l'étude sur l'ensemble des zones ne trouve pas d'effet sur l'emploi."),
  ("Les salariés sont volontaires et mieux payés.", "Le volontariat et les majorations sont des garanties importantes, obtenues par accord collectif. Mais l'étude de l'Insee montre que l'emploi des parents isolés a fortement chuté : ceux qui ne peuvent pas travailler le dimanche sont écartés."),
 ],
 questions=["Si tu ne gagnes pas plus, dépenserais-tu davantage parce que les magasins ouvrent le dimanche, ou achèterais-tu simplement un autre jour ?", "Qui garde les enfants des caissières et des vendeurs quand ils travaillent le dimanche ?"],
 limites=["L'étude de Goux et Maurin a été lue à travers le résumé de sa page sur le site de l'Insee : le texte intégral (méthode, chiffres détaillés) n'a pas pu être ouvert. C'est un document de travail, qui n'engage pas l'Insee.", "Le rapport de l'Assemblée nationale lu est le tome II (comptes rendus) ; le tome I (conclusions) n'a pas été ouvert.", "Le billet de l'OFCE date de 2008 et porte notamment sur l'Allemagne.", "L'étude de la Dares sur le travail du dimanche n'a pas été ouverte directement : ses chiffres viennent d'un article de la Banque des Territoires.", "Les documents ont été lus à travers un outil de lecture qui résume ; les citations sont à revérifier mot pour mot."],
 publics={'convaincus': "L'idée paraît de bon sens, mais les chercheurs de l'Insee qui ont étudié les zones ouvertes le dimanche depuis 2016 n'ont trouvé aucune hausse des effectifs ni du chiffre d'affaires. Les gens ne dépensent pas plus parce que les magasins ouvrent : ils achètent un autre jour. Et ce sont les mères seules qui ont perdu leur emploi dans ces zones.",
  'indecis': "C'est vrai que c'est pratique de faire ses courses le dimanche, et certains salariés apprécient les majorations. Mais la promesse d'emplois n'est pas confirmée : l'évaluation de l'Insee n'en trouve pas, et les députés regrettaient en 2018 qu'aucune étude ne les chiffre. Le dimanche commun, c'est aussi la vie de famille de ceux qui travaillent dans le commerce."},
 a_actualiser='2027-11-30', raison="Nouvelles évaluations du travail dominical ou projet d'extension de l'ouverture des commerces le dimanche.",
))



